param([string]$BaseUrl='http://localhost:8080')
$ErrorActionPreference='Stop'
$u="token_con_$(Get-Random -Minimum 100000 -Maximum 999999)";$r=Invoke-RestMethod "$BaseUrl/api/auth/register" -Method Post -ContentType application/json -Body (@{username=$u;password='TokenCon_2026'}|ConvertTo-Json);$h=@{Authorization="Bearer $($r.data.token)"};$a=Invoke-RestMethod "$BaseUrl/api/addresses" -Method Post -Headers $h -ContentType application/json -Body (@{receiverName='Token';phone='13800138000';province='上海市';city='上海市';district='浦东新区';detail='并发';defaultAddress=$true}|ConvertTo-Json);$c=Invoke-RestMethod "$BaseUrl/api/cart-items" -Method Post -Headers $h -ContentType application/json -Body '{"productId":3,"quantity":1}';$t=Invoke-RestMethod "$BaseUrl/api/orders/tokens" -Method Post -Headers $h -ContentType application/json -Body (@{cartItemIds=@($c.data.id)}|ConvertTo-Json);$body=@{addressId=$a.data.id;cartItemIds=@($c.data.id);idempotencyToken=$t.data.token}|ConvertTo-Json -Compress
$jobs=1..5|ForEach-Object{Start-Job -ArgumentList $BaseUrl,$h,$body -ScriptBlock {param($url,$headers,$payload);$x=Invoke-WebRequest "$url/api/orders" -Method Post -Headers $headers -ContentType application/json -Body $payload -SkipHttpErrorCheck;[int]$x.StatusCode}};$codes=$jobs|Wait-Job|Receive-Job;$jobs|Remove-Job;$ok=@($codes|Where-Object{$_-eq200}).Count;$conflict=@($codes|Where-Object{$_-eq409}).Count;if($ok-ne1-or$conflict-ne4){throw "REDIS-013 expected 1 success/4 conflict, got $($codes-join ',')"};Write-Host 'PASS: REDIS-013 atomic token consumption.'
